      "name": "nuclear_spin_lattice_relaxation_rate",
      "definition": "Electron-induced nuclear spin-lattice relaxation rate 1/T_E, defined as -dot(beta)/beta in the dark.",
      "unit": "1/s",
      "statistic": "Theoretical prediction from Eq. (eq:TE).",
      "uncertainty": "none",
      "resolution": null,
      "anchors": [
